setup.command:
set -e
command -v qemu-i386-static >/dev/null 2>&1 || {
  apt-get update -qq && apt-get install -y -qq qemu-user-static; }
command -v ninja >/dev/null 2>&1 || {
  apt-get update -qq && apt-get install -y -qq ninja-build; }
mkdir -p build/tools build/compilers
[ -x build/tools/wibo ] || {
  curl -sSL -m 300 -o build/tools/wibo https://github.com/decompals/wibo/releases/download/0.7.0/wibo
  chmod +x build/tools/wibo; }
[ -x build/tools/wibo-qemu ] || {
  printf "%s
" "#!/bin/sh" "exec qemu-i386-static \"$(dirname "$0")/wibo\" \"$@\"" > build/tools/wibo-qemu
  chmod +x build/tools/wibo-qemu; }
[ -d build/compilers/GC ] || {
  curl -sSL -m 600 -o build/compilers.zip https://files.decomp.dev/compilers_20251118.zip
  (cd build/compilers && unzip -q ../compilers.zip); }
[ -x build/tools/binutils/powerpc-eabi-objdump ] || {
  curl -sSL -m 300 -o build/binutils.zip https://github.com/encounter/gc-wii-binutils/releases/download/2.42-2/linux-x86_64.zip
  mkdir -p build/tools/binutils
  unzip -q -o build/binutils.zip -d build/tools/binutils
  chmod +x build/tools/binutils/*; }
